/* ---------------------------------------------------------------------------
 * SCALE CONTEXT
 *
 * The single most useful thing this file does. A demonstration that models 156
 * taxpayers can quietly read as though it covers the state; setting the modelled
 * counts against the published ones makes the gap explicit and checkable.
 * ------------------------------------------------------------------------- */
export function scaleContext(modelledTaxpayers, modelledDistricts) {
  const officialDealers = OFFICIAL_FIGURES.find(f => f.id === 'mh-sgst-dealers').value
  return {
    modelledTaxpayers,
    officialDealers,
    officialDealersDisplay: '10,11,501',
    taxpayerRatio: Math.round(officialDealers / Math.max(1, modelledTaxpayers)),
    modelledDistricts,
    officialDistricts: 36,
    source: MAHAGST_STATS,
    asAt: '1 April 2025'
  }
}
